class Solution {
public:
    double frogPosition(int n, vector<vector<int>>& edges, int t, int target) {
        vector<vector<int>> g(n + 1);
        for (auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        queue<tuple<int, int, int, double>> q;
        q.emplace(1, 0, 0, 1.0);
        while (!q.empty()) {
            int u, parent, sec; double prob;
            tie(u, parent, sec, prob) = q.front(); q.pop();
            int choices = 0;
            for (int v : g[u]) if (v != parent) ++choices;
            if (u == target) return (sec == t || choices == 0) ? prob : 0.0;
            if (sec == t || choices == 0) continue;
            for (int v : g[u]) if (v != parent)
                q.emplace(v, u, sec + 1, prob / choices);
        }
        return 0.0;
    }
};
